import os, glob, re, json

def load_grids():
    """Load all demo pairs and test input from session log"""
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    with open(session_file, 'r') as f:
        content = f.read().replace('\\n', '\n')

    grids = {}
    # Parse demo pairs and test input
    # Pattern: "Demo pair N input (HxW):" and "Demo pair N output (HxW):" and "Test input (HxW):"
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    matches = list(re.finditer(pattern, content))

    for i, m in enumerate(matches):
        label, label_type, h, w = m[1], m[2], int(m[3]), int(m[4])
        # Extract rows after this match until the next match or end
        start = m.end()

        # For input/output pairs, grab the next label to know when to stop
        if i < len(matches) - 1:
            end = matches[i+1].start()
        else:
            end = None

        if end is None:
            end = len(content)

        rows_text = content[start:end]
        rows = [r.split() for r in rows_text.split('\n') if r.strip()]

        if label_type == 'input':
            grids[label + '_input'] = [[int(x) for x in r] for r in rows][:h]
        elif label_type == 'output':
            grids[label + '_output'] = [[int(x) for x in r] for r in rows][:h]

    return grids

grids = load_grids()
print("Found grids:")
for k in sorted(grids.keys()):
    print(f"  {k}: {grids[k][:2]}... (len={len(grids[k])})" if len(grids[k]) > 2 else f"  {k}: {grids[k]}")

